// Merge estado previo + mensaje del usuario en un solo payload
const msg = $('Telegram Trigger').first().json.message;
const userText = msg.text || '';
const chatId = msg.chat.id;
const userName = msg.from.first_name || 'usuario';
const today = new Date().toISOString().slice(0, 10);

// Estado previo (si existe)
const stateRows = $input.first().json;
let pending = null;
let memory = null;

if (Array.isArray(stateRows) && stateRows.length > 0) {
  const state = stateRows[0];
  const ptype = state.pending_type;
  if (ptype === 'confirmation') {
    pending = state.pending_action;
  } else if (ptype === 'clarification') {
    memory = state.pending_action;
  }
}

// Construir el mensaje enriquecido para Claude
const userMessageForClaude = [
  'HOY: ' + today,
  'USUARIO: ' + userName,
  'PENDING: ' + (pending ? JSON.stringify(pending) : 'null'),
  'MEMORY: ' + (memory ? JSON.stringify(memory) : 'null'),
  'MENSAJE: ' + userText
].join('\n');

return [{
  json: {
    chat_id: chatId,
    user_text: userText,
    user_name: userName,
    today,
    pending,
    memory,
    claude_user_message: userMessageForClaude
  }
}];

// Parsear la respuesta de Gemini (responseMimeType=application/json ya fuerza JSON puro)
const resp = $input.first().json;
const rawText = resp.candidates?.[0]?.content?.parts?.[0]?.text || '';

let parsed;
try {
  const cleaned = rawText.trim()
    .replace(/^```json\s*/, '').replace(/^```\s*/, '').replace(/\s*```$/, '');
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = { action: 'error', reply: '❌ Error parseando respuesta del bot. Intenta de nuevo con un comando más simple.' };
}

const ctx = $('Prepare Claude Input').first().json;

return [{
  json: {
    ...parsed,
    _chat_id: ctx.chat_id,
    _user_text: ctx.user_text,
    _today: ctx.today,
    _pending: ctx.pending,
    _memory: ctx.memory
  }
}];

// Ejecutar la acción del PENDING (ya confirmada por el usuario)
const pending = $json._pending;
if (!pending) {
  return [{ json: { _chat_id: $json._chat_id, reply: '❌ No había nada pendiente para confirmar.' } }];
}
return [{ json: { ...pending, _chat_id: $json._chat_id } }];

// Ejecuta la acción real según payload.type (después de confirmed)
// Recibe: { type, cama_id, plantas?, sensor_asignado?, bitacora?, _chat_id }
const item = $input.first().json;
const type = item.type;

let url, method, body;
const headers = {
  'apikey': 'sb_publishable_VzKz-KApgtUosdpch3mdVQ_Ojt4pEp0',
  'Authorization': 'Bearer sb_publishable_VzKz-KApgtUosdpch3mdVQ_Ojt4pEp0',
  'Content-Type': 'application/json',
  'Prefer': 'return=representation'
};

const base = 'https://pzkxbymwvimwnfmqoihj.supabase.co/rest/v1/';

if (type === 'update_plantas') {
  url = base + 'huerta_camas?cama_id=eq.' + encodeURIComponent(item.cama_id);
  method = 'PATCH';
  body = { plantas: item.plantas, updated_by: 'telegram' };
} else if (type === 'add_plantas' || type === 'remove_plantas') {
  // Necesita leer primero
  // Para MVP hacemos fetch sync con http.request
  const getUrl = base + 'huerta_camas?cama_id=eq.' + encodeURIComponent(item.cama_id) + '&select=plantas';
  const getResp = await this.helpers.httpRequest({ method: 'GET', url: getUrl, headers, json: true });
  const current = (getResp[0]?.plantas) || [];
  let newPlantas;
  if (type === 'add_plantas') {
    const set = new Set([...current, ...item.plantas]);
    newPlantas = [...set];
  } else {
    newPlantas = current.filter(p => !item.plantas.includes(p));
  }
  url = base + 'huerta_camas?cama_id=eq.' + encodeURIComponent(item.cama_id);
  method = 'PATCH';
  body = { plantas: newPlantas, updated_by: 'telegram' };
} else if (type === 'update_sensor') {
  url = base + 'huerta_camas?cama_id=eq.' + encodeURIComponent(item.cama_id);
  method = 'PATCH';
  body = { sensor_asignado: item.sensor_asignado, updated_by: 'telegram' };
} else if (type === 'add_bitacora') {
  url = base + 'huerta_bitacora';
  method = 'POST';
  const b = item.bitacora;
  body = {
    local_id: 'tg_' + item._chat_id + '_' + Date.now(),
    fecha: b.fecha,
    cama_id: b.cama_id,
    tipo: b.tipo,
    planta_id: b.planta_id || null,
    cantidad: b.cantidad ?? null,
    unidad: b.unidad || null,
    nota: b.nota || null,
    created_by: 'telegram'
  };
}

const resp = await this.helpers.httpRequest({ method, url, headers, body, json: true });

return [{
  json: {
    _chat_id: item._chat_id,
    _executed_type: type,
    _result: resp,
    reply: '✅ Listo. Acción ejecutada.'
  }
}];

// Formatea la respuesta final para Telegram.
// Llega desde distintas ramas con distintos shapes.
const item = $input.first().json;

let reply = item.reply || '';
let chat_id = item._chat_id || item.chat_id;

// Caso: query_cama devuelve array de Supabase
if (Array.isArray(item)) {
  if (item.length > 1 || (item[0] && item[0].cama_id && item[0].orden !== undefined)) {
    // list_camas
    const lines = item.map(c => {
      const plantas = (Array.isArray(c.plantas) && c.plantas.length)
        ? c.plantas.join(', ')
        : '_sin ocupación_';
      const sensor = c.sensor_asignado ? c.sensor_asignado.replace('soil_', '').toUpperCase() : '—';
      return '• ' + c.nombre + ' (' + c.grupo + ') · ' + sensor + '\n  ' + plantas;
    });
    reply = '🌿 Camas de la huerta:\n\n' + lines.join('\n');
  } else if (item.length === 1) {
    // query_cama
    const c = item[0];
    const plantas = (Array.isArray(c.plantas) && c.plantas.length)
      ? c.plantas.join(', ')
      : 'sin ocupación';
    const sensor = c.sensor_asignado ? c.sensor_asignado.replace('soil_', '').toUpperCase() : 'sin sensor';
    reply = '📍 ' + c.nombre + '\nGrupo: ' + c.grupo + '\nSensor: ' + sensor + '\nPlantas: ' + plantas;
  } else {
    reply = '⚠️ No encontré esa cama.';
  }
  chat_id = $('Prepare Claude Input').first().json.chat_id;
}

// Caso: execute-action devuelve reply "✅ Listo"
if (item._executed_type) {
  const type = item._executed_type;
  if (type === 'update_plantas' || type === 'add_plantas' || type === 'remove_plantas') {
    reply = '✅ Plantas actualizadas.';
  } else if (type === 'update_sensor') {
    reply = '✅ Sensor actualizado.';
  } else if (type === 'add_bitacora') {
    reply = '✅ Entrada de bitácora registrada.';
  }
}

if (!chat_id) chat_id = $('Telegram Trigger').first().json.message.chat.id;
if (!reply) reply = '✅ OK';

return [{ json: { chat_id, reply } }];
